const { useEffect, useState } = React;

function Counter() {
  const [count, setCount] = useState(0);

  useEffect(() => {
    document.querySelector('#effect-value').textContent = count;
  }, [count]);

  return <button type="button" onClick={() => setCount(count + 1)}>숫자: {count}</button>;
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Counter />);
